insert into public.requirement_details (requirement_id, lang, description, how_to_comply) values ('af282c94-ee59-faa0-8a3e-7c9b83126e07', 'ru', 'Дополнительно, в соответствии с изменениями, внесёнными в законодательство в 2023 году (ЗРУ-878 от 15.11.2023), незаконное использование чужого товарного знака или обозначения, сходного до степени смешения, может привести к более серьёзным последствиям. Среди них — конфискация продукции и доходов, полученных от её реализации, а также судебное предписание о прекращении использования обозначения и уничтожении упаковки или иных материалов, содержащих нарушающий знак.', '[{"step":"Рекомендуется заранее зарегистрировать торговое наименование, поскольку в случае, если выбранное название уже зарегистрировано другим лицом, продукция с таким обозначением подлежит изъятию из продажи, а нарушитель может быть оштрафован. Согласно Закону Республики Узбекистан «О товарных знаках, знаках обслуживания и наименованиях мест происхождения товаров» №267-II от 30.08.2001 года, правовая охрана товарного знака предоставляется только после его официальной регистрации. Использование чужого зарегистрированного товарного знака без согласия правообладателя считается нарушением исключительных прав и может повлечь административную ответственность, включая штраф и обязанность возместить убытки правообладателю в судебном порядке."}]'::jsonb) on conflict do nothing;
