insert into public.requirement_contents (requirement_id, lang, title) values ('3dbba131-2a9e-7242-4b37-795cf2a9c4de', 'ru', 'Зарегистрировать внешнеторговый контракт в ЕЭИСВО') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply) values ('3dbba131-2a9e-7242-4b37-795cf2a9c4de', 'ru', null, '[{"step":"Предприниматель должен зарегистрировать внешнеторговый контракт в Единой электронной информационной системе внешнеторговых операций (ЕЭИСВО). Для этого предприниматель создает электронную копию контракта в программе («Е-Контракт 2» или «ВЭД-Контракт») и отправляет этот файл в ЕЭИСВО через «Единый портал интерактивных государственных услуг» (ЕПИГУ).\nКоммерческие банки, Министерство инвестиций и внешней торговли, Государственный налоговый комитет, Государственный таможенный комитет и другие контролирующие агентства используют информацию для мониторинга внешнеторговых операций и обмена информации между предпринимателями, таможенными и налоговыми органами."}]'::jsonb) on conflict do nothing;
