insert into public.requirement_details (requirement_id, lang, description, how_to_comply) values ('dcaea7c3-9d67-ee68-efbe-62acd1e22064', 'ru', null, '[{"step":"Импортер должен обеспечить хранение ввозимых товаров в процессе таможенного оформления либо на таможенных складах, либо по разрешению властей на своих собственных объектах, если они соответствуют требуемым условиям хранения.\nИмпортер должен заключить с выбранным таможенным складом договор на хранение товаров на его территории."}]'::jsonb) on conflict do nothing;
